-- Rückbau 203 (Update-Knopf): Funktionen ally_update_* aus Migration 203, die Tabelle ally_update_stand und die Benachrichtigungsart update_verfuegbar entfernen.
-- Vorher ALLY 20 und ALLY 23 sowie die Web-App auf den Stand vor 203 zurücksetzen und das Update-Programm auf dem Server abschalten (docs/updates.md, Rückbau).
-- Keine Daten gehen verloren: der Stand, die Benachrichtigungen und die Schalter der Art update_verfuegbar kommen vorher in die Sicherungstabellen
-- ally_update_stand_rb203, ally_benachrichtigungen_rb203, ally_benachrichtigung_schalter_rb203. Das Protokoll ally_updates (Migration 188) bleibt.
-- Nur auf dem Stand von 203. Läuft als Ganzes in der Transaktion des Aufrufs (psql -1).
DO $m$
BEGIN
  IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relkind = 'r' AND c.relname::text COLLATE "C" = 'ally_update_stand') = 0 AND (SELECT md5(string_agg(p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')|' || pg_get_function_result(p.oid) || '|' || md5(p.prosrc), E'\n' ORDER BY p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')' COLLATE "C")) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname::text = 'public' COLLATE "C" AND p.proname::text COLLATE "C" = ANY (ARRAY['ally_update_nummer', 'ally_update_stand_zeile', 'ally_update_installiert', 'ally_update_offen', 'ally_update_frist', 'ally_update_empfaenger', 'ally_update_ui', 'ally_update_ui_aktion', 'ally_update_host_plan', 'ally_update_host_verfuegbar', 'ally_update_host_schritt', 'ally_update_host_ende', 'ally_update_host_zurueckgesetzt'])) IS NULL AND (SELECT count(*) FROM ally_benachrichtigung_arten x WHERE x.schluessel COLLATE "C" = 'update_verfuegbar') = 0 THEN RAISE EXCEPTION 'Rückbau 203: schon zurückgebaut, nichts geändert'; END IF;
  IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relkind = 'r' AND c.relname::text COLLATE "C" = 'ally_update_stand') <> 1 OR (SELECT md5(string_agg(z, E'\n' ORDER BY z COLLATE "C")) FROM (WITH t AS (SELECT c.oid, c.relname::text AS tab FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relkind::text = ANY (ARRAY['r', 'p']) AND c.relname::text = ANY (ARRAY['ally_update_stand'])) SELECT 'S|' || t.tab || '|' || a.attname::text || '|' || format_type(a.atttypid, a.atttypmod) || '|' || CASE WHEN a.attnotnull THEN 'NN' ELSE '-' END || '|' || coalesce(pg_get_expr(d.adbin, d.adrelid), '') || '|' || a.attidentity::text || a.attgenerated::text AS z FROM t JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum > 0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid = t.oid AND d.adnum = a.attnum UNION ALL SELECT 'C|' || t.tab || '|' || co.conname::text || '|' || co.contype::text || '|' || pg_get_constraintdef(co.oid) FROM t JOIN pg_constraint co ON co.conrelid = t.oid UNION ALL SELECT 'I|' || t.tab || '|' || ic.relname::text || '|' || pg_get_indexdef(i.indexrelid) FROM t JOIN pg_index i ON i.indrelid = t.oid JOIN pg_class ic ON ic.oid = i.indexrelid UNION ALL SELECT 'T|' || t.tab || '|' || tg.tgname::text || '|' || pg_get_triggerdef(tg.oid) || '|' || tg.tgenabled::text FROM t JOIN pg_trigger tg ON tg.tgrelid = t.oid AND NOT tg.tgisinternal) x) IS DISTINCT FROM '262cae808bacef79d2fc48bd44ca308d' THEN RAISE EXCEPTION 'Rückbau 203: Tabelle nicht im Stand von 203, nichts geändert'; END IF;
  IF (SELECT md5(string_agg(p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')|' || pg_get_function_result(p.oid) || '|' || md5(p.prosrc), E'\n' ORDER BY p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')' COLLATE "C")) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname::text = 'public' COLLATE "C" AND p.proname::text COLLATE "C" = ANY (ARRAY['ally_update_nummer', 'ally_update_stand_zeile', 'ally_update_installiert', 'ally_update_offen', 'ally_update_frist', 'ally_update_empfaenger', 'ally_update_ui', 'ally_update_ui_aktion', 'ally_update_host_plan', 'ally_update_host_verfuegbar', 'ally_update_host_schritt', 'ally_update_host_ende', 'ally_update_host_zurueckgesetzt'])) IS DISTINCT FROM '135ac6b7a33661d8a5c4a6086ab587f1' THEN RAISE EXCEPTION 'Rückbau 203: Funktionen nicht im Stand von 203, nichts geändert'; END IF;
  IF (SELECT count(*) FROM ally_benachrichtigung_arten x WHERE x.schluessel COLLATE "C" = 'update_verfuegbar') <> 1 THEN RAISE EXCEPTION 'Rückbau 203: Benachrichtigungsart update_verfuegbar fehlt, nichts geändert'; END IF;
  IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relname::text COLLATE "C" = ANY (ARRAY['ally_update_stand_rb203', 'ally_benachrichtigungen_rb203', 'ally_benachrichtigung_schalter_rb203'])) <> 0 THEN RAISE EXCEPTION 'Rückbau 203: Sicherungstabellen _rb203 schon vorhanden, nichts geändert'; END IF;
  PERFORM set_config('m203.inhalt', (SELECT md5(string_agg(z, E'\n' ORDER BY z COLLATE "C")) FROM (SELECT '0|' || coalesce(md5(string_agg(to_jsonb(x)::text, E'\n' ORDER BY to_jsonb(x)::text COLLATE "C")), '-') AS z FROM (SELECT * FROM public.ally_update_stand) x UNION ALL SELECT '1|' || coalesce(md5(string_agg(to_jsonb(x)::text, E'\n' ORDER BY to_jsonb(x)::text COLLATE "C")), '-') AS z FROM (SELECT * FROM public.ally_benachrichtigungen WHERE art COLLATE "C" = 'update_verfuegbar') x UNION ALL SELECT '2|' || coalesce(md5(string_agg(to_jsonb(x)::text, E'\n' ORDER BY to_jsonb(x)::text COLLATE "C")), '-') AS z FROM (SELECT * FROM public.ally_benachrichtigung_schalter WHERE art COLLATE "C" = 'update_verfuegbar') x) y), true);
END $m$;
CREATE TABLE public.ally_update_stand_rb203 AS SELECT * FROM public.ally_update_stand;
CREATE TABLE public.ally_benachrichtigungen_rb203 AS SELECT * FROM public.ally_benachrichtigungen WHERE art COLLATE "C" = 'update_verfuegbar';
CREATE TABLE public.ally_benachrichtigung_schalter_rb203 AS SELECT * FROM public.ally_benachrichtigung_schalter WHERE art COLLATE "C" = 'update_verfuegbar';
DO $m$
BEGIN
  IF current_setting('m203.inhalt') IS DISTINCT FROM (SELECT md5(string_agg(z, E'\n' ORDER BY z COLLATE "C")) FROM (SELECT '0|' || coalesce(md5(string_agg(to_jsonb(x)::text, E'\n' ORDER BY to_jsonb(x)::text COLLATE "C")), '-') AS z FROM (SELECT * FROM public.ally_update_stand_rb203) x UNION ALL SELECT '1|' || coalesce(md5(string_agg(to_jsonb(x)::text, E'\n' ORDER BY to_jsonb(x)::text COLLATE "C")), '-') AS z FROM (SELECT * FROM public.ally_benachrichtigungen_rb203) x UNION ALL SELECT '2|' || coalesce(md5(string_agg(to_jsonb(x)::text, E'\n' ORDER BY to_jsonb(x)::text COLLATE "C")), '-') AS z FROM (SELECT * FROM public.ally_benachrichtigung_schalter_rb203) x) y) THEN RAISE EXCEPTION 'Rückbau 203: Sicherung der Daten unvollständig, nichts geändert'; END IF;
END $m$;
DELETE FROM public.ally_benachrichtigungen WHERE art COLLATE "C" = 'update_verfuegbar';
DELETE FROM public.ally_benachrichtigung_schalter WHERE art COLLATE "C" = 'update_verfuegbar';
DELETE FROM public.ally_benachrichtigung_arten WHERE schluessel COLLATE "C" = 'update_verfuegbar';
